import frameIds from "@/lib/videoFrameIds.json";

const FRAMES = new Set<string>(frameIds as string[]);

/**
 * Placeholder image for a YouTube video: a real still ~20s into the video
 * (generated by scripts/extract-video-frames.sh), falling back to YouTube's
 * default thumbnail for videos without an extracted frame (e.g. added later via CMS).
 */
export function videoThumb(id: string): string {
  return FRAMES.has(id)
    ? `/images/media/video-frames/${id}.jpg`
    : `https://img.youtube.com/vi/${id}/hqdefault.jpg`;
}
